export function weekOf(at){const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(at));const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10);}
export function recordRecoveries(state,subject,ids,at){const earned={...(state.earned||{})},weeks={...(state.weeks||{})},week=weekOf(at),fresh=[...new Set(ids)].filter(id=>typeof id==='string'&&id&&!earned[subject+':'+id]);for(const id of fresh)earned[subject+':'+id]={at,week};if(fresh.length)weeks[week]={count:(weeks[week]?.count||0)+fresh.length,name:'Memory Star Lantern'};return{state:{version:1,earned,weeks},added:fresh.length,week};}
